	/**
	 * Default Constructor
	 */
    public ConnectedAircraftService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ConnectedAircraftEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ConnectedAircraftRepository.class) );
		this.validator		= applicationContext.getBean(ConnectedAircraftValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ConnectedAircraft
	 */
		public ConnectedAircraft createConnectedAircraft( CreateConnectedAircraftCommand command ) {

		ConnectedAircraft entity = new ConnectedAircraft();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setConnectedAircraftId( command.getConnectedAircraftId() );
            entity.setCommunicationsProvider( command.getCommunicationsProvider() );
            entity.setConnectivityStatus( command.getConnectivityStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ConnectedAircraft {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateConnectedAircraftCommand
	 * @return		ConnectedAircraft
	 */
	public ConnectedAircraft updateConnectedAircraft( UpdateConnectedAircraftCommand command ) {

		ConnectedAircraft entity = new ConnectedAircraft();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setConnectedAircraftId( command.getConnectedAircraftId() );
            entity.setCommunicationsProvider( command.getCommunicationsProvider() );
            entity.setAircraft( command.getAircraft() );
            entity.setFlightHealthEvents( command.getFlightHealthEvents() );
            entity.setSoftwareLoads( command.getSoftwareLoads() );
            entity.setConnectivityStatus( command.getConnectivityStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of ConnectedAircraft {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteConnectedAircraftCommand
	 */
	public void delete( DeleteConnectedAircraftCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getConnectedAircraftId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of ConnectedAircraft {0} ", id );

	}

	/**
	 * Method to retrieve the ConnectedAircraft via ConnectedAircraftFetchOneSummary
	 * @param 	summary ConnectedAircraftFetchOneSummary
	 * @return 	ConnectedAircraftFetchOneResponse
	 */
	public ConnectedAircraft getConnectedAircraft( ConnectedAircraftFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ConnectedAircraftFetchOneSummary arg cannot be null" );

		ConnectedAircraft entity = null;
		UUID id = summary.getConnectedAircraftId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a ConnectedAircraft using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all ConnectedAircrafts
	 *
	 * @return 	List<ConnectedAircraft>
	 */
    public List<ConnectedAircraft> getAllConnectedAircraft() {
		List<ConnectedAircraft> list = projector.findAll( new FindAllConnectedAircraftQuery() );
		return list;
	}

	/**
	 * assign Aircraft on ConnectedAircraft
	 * @param		command AssignAircraftToConnectedAircraftCommand
	 */
	public void assignAircraft( AssignAircraftToConnectedAircraftCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignAircraft(command.getConnectedAircraftId(), command.getAssignment());

	}

